        WHERE c.conrelid = to_regclass('tax.efaktur_documents') AND c.contype = 'f' AND a.attname = 'tax_transaction_id'
    ) THEN
        ALTER TABLE tax.efaktur_documents ADD CONSTRAINT fk_efaktur_documents_tax_transaction_id FOREIGN KEY (tax_transaction_id) REFERENCES tax.tax_transactions (id) NOT VALID;
