            ALTER TABLE tax.efaktur_documents VALIDATE CONSTRAINT fk_efaktur_documents_tax_transaction_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_efaktur_documents_tax_transaction_id left NOT VALID: stored rows of tax.efaktur_documents reference missing rows';
        END;
    END IF;
END $$;

